'use strict';
(()=>{const G=GeoEngine,W=SpatiaWorkspace,M=BuildModel;let model;try{model=G.validate(JSON.parse(localStorage.getItem(W.MODEL_KEY)))}catch{model=G.seed()}globalThis.SPATIA_ACTIVE_MODEL=model;const originalSeed=M.seed;M.activeUnit=model.elements.some(e=>e.unit==='302')?'302':model.elements[0].unit;M.units=[...new Set(model.elements.map(e=>e.unit))];M.seed=()=>W.reconcile(W.buildingId(model)==='forest-a-demo'?originalSeed():{version:2,requests:[],records:[],notices:[],materials:[]},model);const requests=M.visibleRequests,records=M.visibleRecords;M.visibleRequests=(state,role,unit=M.activeUnit)=>requests(state,role,unit);M.visibleRecords=(state,role,unit=M.activeUnit)=>records(state,role,unit);})();
